<script setup>import{ref,onMounted}from'vue';import{useRoute}from'vue-router';import api from'../services/api';import{addToCart}from'../stores';const route=useRoute(),p=ref(null);onMounted(async()=>{try{p.value=(await api.get('/products/'+route.params.slug)).data}catch{}})</script><template><section v-if="p" class="grid gap-10 md:grid-cols-2"><div class="aspect-square rounded-3xl bg-slate-100"><img v-if="p.imageUrl" :src="p.imageUrl" class="h-full w-full rounded-3xl object-cover"/></div><div class="py-5"><span class="font-bold text-indigo-600">PRODUCT</span><h1 class="mt-3 text-4xl font-black">{{p.name}}</h1><p class="mt-5 text-3xl font-black">{{Number(p.price).toLocaleString()}} {{p.currency||'ETB'}}</p><p class="mt-5 leading-7 text-slate-600">{{p.description}}</p><button @click="addToCart(p)" class="mt-8 rounded-xl bg-indigo-600 px-6 py-3 font-bold text-white">Add to cart</button></div></section><div v-else class="py-20 text-center">Loading product…</div></template>